/**
 * @file NetworkLevelingCarryRunEnd.cpp
 * @brief Run-end reports of the phase-leveling carry: the retirement census and the phase-colour state (card LGM).
 *
 * The leveling carry is injected by the PASS B assembly and harvested by
 * networkHarvestLocalCarries (app/NetworkLocalCarryHarvest.cpp); neither has a seam of its
 * own.
 *
 * Generated by scripts/nom_td_cut.py from the frozen teardown (card NOM step TD1b);
 * scripts/nom_td_verify.py proves every body against it.  The table that orders the
 * reports is filter/NetworkRunEnd.cpp.
 */

#include "filter/NetworkLevelingCarryRunEnd.hpp"

#include "app/NetworkRunContext.hpp"
#include "config/GnssConfig.hpp"
#include "filter/NetworkRunEnd.hpp"
#include "filter/NetworkRunGroups.hpp"
#include "filter/NetworkRunTypes.hpp"
